65	    public void assignCustomerCode(int ownerCount) {
66	        String prefix = getLastName().substring(0, Math.min(3, getLastName().length())).toUpperCase(Locale.ROOT);
67	        this.customerCode = String.format("%s-%04d", prefix, ownerCount + 1);
68	    }
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    public java.time.LocalDate getRegistrationDate() {
74	        return this.registrationDate;
75	    }
76	
77	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
78	        this.registrationDate = registrationDate;
79	    }
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
